_choice_gdb_command() {
    gdb -q -batch -ex 'complete ' 2>/dev/null
}

_choice_pid() {
    command -v ps >/dev/null || return 0
    ps -eo pid=,comm= | gawk 'NF >= 2 {
        pid = $1
        sub(/^[[:space:]]*[^[:space:]]+[[:space:]]+/, "")
        print pid "\t" $0
    }'
}
